// Order window to load: from lookbackDays ago until now. It must reach further back than lapsedDays.
const cfg = $('Config').first().json;
const num = (v, d) => (Number.isFinite(Number(v)) && Number(v) > 0 ? Number(v) : d);
const lapsedDays = num(cfg.lapsedDays, 90);
const lookbackDays = Math.max(num(cfg.lookbackDays, 365), lapsedDays + 1);
const after = new Date(Date.now() - lookbackDays * 24 * 3600 * 1000).toISOString();
return [{ json: { after, lapsedDays, lookbackDays } }];

// Group the loaded orders by customer and pick customers whose last paid order is older than lapsedDays.
// Anyone with a newer order of any status, a recent win-back message or an excluded address is skipped.
const cfg = $('Config').first().json;
const range = $('Date range').first().json;
const DAY = 24 * 3600 * 1000;
const now = Date.now();
const num = (v, d) => (Number.isFinite(Number(v)) && Number(v) > 0 ? Number(v) : d);
const lapsedDays = num(range.lapsedDays ?? cfg.lapsedDays, 90);
const cooldownDays = num(cfg.cooldownDays, 180);
const minOrders = num(cfg.minOrders, 1);
const maxPerRun = num(cfg.maxPerRun, 50);
const PAID = ['completed', 'processing', 'on-hold'];

function normalizePhone(raw, cc) {
  let d = String(raw || '').replace(/\D/g, '');
  if (d.startsWith('00')) d = d.slice(2);
  if (!d) return '';
  if (d.startsWith(cc)) return d;
  if (d.startsWith('0')) return cc + d.slice(1);
  return cc + d;
}
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const cc = String(cfg.defaultCountryCode || '');
const excluded = new Set(String(cfg.excludeEmails || '').split(/[\s,;]+/).map((e) => e.trim().toLowerCase()).filter(Boolean));
const createdAt = (o) => Date.parse(o.date_created_gmt ? String(o.date_created_gmt).replace(/Z?$/, 'Z') : o.date_created);

const orders = $input.all().map((i) => i.json).filter((o) => o && o.id);
const recent = new Set(); // email or phone of customers who ordered within lapsedDays (any status)
const customers = new Map();
for (const o of orders) {
  const b = o.billing || {};
  const email = String(b.email || '').trim().toLowerCase();
  const phone = normalizePhone(b.phone, cc);
  const at = createdAt(o);
  if (!Number.isFinite(at) || (!email && !phone)) continue;
  if (now - at < lapsedDays * DAY) {
    if (email) recent.add(email);
    if (phone) recent.add(phone);
  }
  if (!PAID.includes(o.status)) continue;
  const key = email || phone;
  const c = customers.get(key) || { key, orders: 0, spent: 0, last: 0 };
  c.orders += 1;
  c.spent += parseFloat(o.total) || 0;
  if (at > c.last) Object.assign(c, { last: at, name: b.first_name || '', email, phone, lastOrderId: o.id, currency: o.currency, currencySymbol: o.currency_symbol });
  customers.set(key, c);
}

// Remember who was contacted so the same customer is not messaged again before cooldownDays.
const state = $getWorkflowStaticData('global');
state.contacted = state.contacted || {};
for (const [k, t] of Object.entries(state.contacted)) {
  if (now - t > cooldownDays * DAY) delete state.contacted[k];
}
const contactedRecently = (c) => [c.email, c.phone].some((k) => k && state.contacted[k]);

const site = String(cfg.siteUrl || '').replace(/\/+$/, '');
const shopUrl = String(cfg.shopUrl || '').trim() || site + '/shop/';
const coupon = String(cfg.couponCode || '').trim();
const offer = String(cfg.offerText || '').trim() || 'a discount on your next order';

const picked = [...customers.values()]
  .filter((c) => c.orders >= minOrders && now - c.last >= lapsedDays * DAY)
  .filter((c) => !recent.has(c.email) && !recent.has(c.phone))
  .filter((c) => !excluded.has(c.email) && !contactedRecently(c))
  .map((c) => ({ ...c, channel: cfg.channel === 'whatsapp' && c.phone ? 'whatsapp' : c.email ? 'email' : '' }))
  .filter((c) => c.channel)
  .sort((a, b) => b.spent - a.spent || b.last - a.last)
  .slice(0, maxPerRun);

for (const c of picked) {
  if (c.email) state.contacted[c.email] = now;
  if (c.phone) state.contacted[c.phone] = now;
}
const keys = Object.keys(state.contacted);
if (keys.length > 5000) keys.slice(0, keys.length - 5000).forEach((k) => delete state.contacted[k]);

return picked.map((c) => {
  const name = c.name || 'there';
  const money = (n) => (c.currencySymbol ? c.currencySymbol + n.toFixed(2) : n.toFixed(2) + ' ' + (c.currency || ''));
  const daysSince = Math.floor((now - c.last) / DAY);
  const params = [name, coupon || '-', shopUrl].map((text) => ({ type: 'text', text: String(text) }));
  return {
    json: {
      customerKey: c.key,
      name,
      email: c.email,
      phone: c.phone,
      channel: c.channel,
      orders: c.orders,
      totalSpent: money(c.spent),
      lastOrderId: c.lastOrderId,
      lastOrderDate: new Date(c.last).toISOString().slice(0, 10),
      daysSinceLastOrder: daysSince,
      couponCode: coupon,
      waMessage: {
        messaging_product: 'whatsapp',
        to: c.phone,
        type: 'template',
        template: { name: cfg.waTemplateWinback, language: { code: cfg.waLanguage }, components: [{ type: 'body', parameters: params }] },
      },
      emailSubject: 'We miss you, ' + name + (coupon ? ' - here is ' + offer : ''),
      emailHtml:
        '<p>Hi ' + esc(name) + ',</p>' +
        '<p>It has been a while since your last order with us, so we wanted to say thank you for shopping with us before.</p>' +
        (coupon ? '<p>Use code <b>' + esc(coupon) + '</b> at checkout for ' + esc(offer) + '.</p>' : '') +
        '<p><a href="' + esc(shopUrl) + '">See what is new in the shop</a></p>' +
        '<p>If you would rather not hear from us, just reply to this email and we will remove you.</p>',
    },
  };
});
